// Chip naming the warbond a weapon or stratagem unlocks from (dist/data/warbond-sources.js,
// generated by scripts/build-warbonds.mjs), linking to that item on the warbond board.
import { warbondSources } from '../data/warbond-sources.js';
import { formatRoute } from '../core/route.js';
import { html, icon } from './dom.js';
import { L } from '../core/i18n.js';

export function warbondChip(view, id) {
  const source = warbondSources[`${view}/${id}`];
  if (!source) return '';
  const free = source.price === 0;
  const href = formatRoute({ view: 'warbonds', id: source.id, query: { item: `${view}/${id}` } });
  const title = free
    ? L(`무료 전쟁 채권 ${source.page}페이지에서 해금`, `Unlocked on page ${source.page} of this free warbond`)
    : L(`전쟁 채권을 구매한 뒤 ${source.page}페이지에서 해금`, `Unlocked on page ${source.page} after buying this warbond`);
  return html`<a class="badge warbond" href="${href}" title="${title}">${icon('warbonds', 14)}${L(source.name, source.en)}${free ? L(' · 무료', ' · free') : ''}</a>`;
}
